<?php class Contact{public static function create($d){$s=db()->prepare('INSERT INTO contacts(name,email,subject,message) VALUES(?,?,?,?)');$s->execute([trim($d['name']),trim($d['email']),trim($d['subject']),trim($d['message'])]);}public static function all(){return db()->query('SELECT * FROM contacts ORDER BY id DESC')->fetchAll();}public static function processed($id){db()->prepare("UPDATE contacts SET status='processed' WHERE id=?")->execute([$id]);}}